/**
 * Toolbar selection tool component for the Kit app.
 *MUST render selection mode toggle buttons.
 **/
export const KitToolbarSelection: FC = () => {
  const store = useKitAppStore();
  const canUndo = useSyncDeep(store, (s: KitAppState | null) => s?.canUndo ?? false);
  const canRedo = useSyncDeep(store, (s: KitAppState | null) => s?.canRedo ?? false);
  const { undo, redo } = useKitAppCommands();
  const undoLabel = useLabel("compose.sketchpad.app.kit.history.undo");
  const redoLabel = useLabel("compose.sketchpad.app.kit.history.redo");
  const [activeTool, setActiveTool] = useKitAppActiveTool();
  const additiveLabel = useLabel("compose.sketchpad.app.kit.tools.select.mode.additive");
  const subtractiveLabel = useLabel("compose.sketchpad.app.kit.tools.select.mode.subtractive");
  const intersectLabel = useLabel("compose.sketchpad.app.kit.tools.select.mode.intersect");
  const rectangularLabel = useLabel("compose.sketchpad.app.kit.tools.select.shape.rectangular");
  const lassoLabel = useLabel("compose.sketchpad.app.kit.tools.select.shape.lasso");
  const handLabel = useLabel("compose.sketchpad.app.kit.tools.select.navigation.hand");

  return (
    <ToolbarGroup>
      <ToolbarGroup>
        <Toggle
          id="compose.sketchpad.app.kit.history.undo"
          icon={<SkipBackIcon className="size-tiny" />}
          text={undoLabel}
          disabled={!canUndo}
          onPressedChange={(pressed) => {
            if (pressed) undo?.();
          }}
        />
        <Toggle
          id="compose.sketchpad.app.kit.history.redo"
          icon={<SkipForwardIcon className="size-tiny" />}
          text={redoLabel}
          disabled={!canRedo}
          onPressedChange={(pressed) => {
            if (pressed) redo?.();
          }}
        />
      </ToolbarGroup>
      <ToolbarDivider />
      <ToolbarGroup>
        <Toggle
          id="compose.sketchpad.app.kit.tools.select.mode.additive"
          icon={<AddIcon className="size-tiny" />}
